async function run() {
  const handle = await tasks.trigger("scheduled-sync-scheduled_sync__UkFBjqw", {
    timestamp: new Date(),
    lastTimestamp: new Date(),
    externalId: "manual-run"
  } as any);
  console.log(`Run ID: ${handle.id}`);
}

run().catch(console.error);

